    'faq_q1' => '<strong>What ni TropaTT?</strong><br>A free fungua-chanzo self-hosted CRM, kazi msimamizi, na mradi management platform.',
    'faq_q10' => 'Who ni developer?',
    'faq_q10_answer' => '<strong>Anton Barinov</strong>, a PHP developer.',
    'faq_q2' => '<strong>Is it a CRM au a kazi msimamizi?</strong><br>Both. A CRM kwa wateja na counterparties, a kazi msimamizi kwa kazi, plus mradi management, chat, kalenda, na AI.',
    'faq_q3' => '<strong>Is it suitable kwa freelancers?</strong><br>Yes. There ni hakuna kiwango cha chini timu ukubwa. A single mtumiaji gets CRM, kazi, an AI siku mpango, na chat bila per-seat fees.',
    'faq_q4' => '<strong>Does it kazi kwenye shared hosting?</strong><br>Yes. PHP 8.1+ na MySQL ni enough. browser installer configures everything.',
    'faq_q5' => '<strong>Are there vikomo kwenye watumiaji na kazi?</strong><br>No. Unlimited watumiaji, kazi, miradi, na wateja. tu limitation ni server capacity.',
    'faq_q6' => '<strong>Where ni data stored?</strong><br>100% kwenye yako server. mfumo never syncs data hadi cloud.',
    'faq_q7' => '<strong>What AI tools ni inapatikana?</strong><br>20+ tools: wazo exploration, siku/wiki mipango, summaries, orodha za ukaguzi, hatari, mkutano preparation.',
    'faq_q8' => '<strong>Is there an API?</strong><br>Yes, a REST API pamoja na an OpenAPI 3.1 spec imeundwa kutoka msimbo.',
    'faq_q9' => '<strong>Can it kuwa customized?</strong><br>Yes. PHP msimbo, moduli, webhooks, API, mtiririko wa kazi rules, maalum sehemu, majukumu, na ufikiaji rights.',
